<?php
namespace App\Services\HR;
use App\Models\AttendancePayrollPeriod;
use App\Models\AttendanceAuditLog;
use Illuminate\Support\Facades\DB;
class AttendancePeriodService { public function assertEditable(string $date): void { $period=AttendancePayrollPeriod::whereDate('period_from','<=',$date)->whereDate('period_to','>=',$date)->latest('id')->first(); if($period?->isLocked())abort(422,'Attendance period is locked for payroll.'); } public function lock(AttendancePayrollPeriod $period,int $actorId,string $action='lock',?string $reason=null): AttendancePayrollPeriod {return DB::transaction(function()use($period,$actorId,$action,$reason){$period=AttendancePayrollPeriod::whereKey($period->id)->lockForUpdate()->firstOrFail();abort_unless($period->status==='finalized',422,'Only finalized periods can be locked.');$period->update(['status'=>'locked','locked_at'=>now(),'locked_by'=>$actorId]);AttendanceAuditLog::create(['user_id'=>$actorId,'action'=>'attendance_locked','new_values'=>$period->toArray(),'reason'=>$reason,'performed_at'=>now(),'source'=>'web']);return $period;});} public function reopen(AttendancePayrollPeriod $period,int $actorId,string $reason): AttendancePayrollPeriod {return DB::transaction(function()use($period,$actorId,$reason){$period=AttendancePayrollPeriod::whereKey($period->id)->lockForUpdate()->firstOrFail();abort_unless(in_array($period->status,['locked','finalized'],true),422,'Period is not locked or finalized.');$period->update(['status'=>'reopened','reopened_at'=>now(),'reopened_by'=>$actorId,'remarks'=>$reason]);AttendanceAuditLog::create(['user_id'=>$actorId,'action'=>'attendance_reopened','new_values'=>$period->toArray(),'reason'=>$reason,'performed_at'=>now(),'source'=>'web']);return $period;});} }
